int longest(List<int> nums) {
  final set = nums.toSet();
  var best = 0;
  for (final n in set) {
    if (set.contains(n - 1)) continue;
    var len = 1;
    while (set.contains(n + len)) {
      len++;
    }
    if (len > best) best = len;
  }
  return best;
}

void main() {
  print(longest([10, 5, 12, 3, 11, 4, 13]));
}
```

