bool iso(String s, String t) {
  final st = <String, String>{}, ts = <String, String>{};
  for (var i = 0; i < s.length; i++) {
    final a = s[i], b = t[i];
    if ((st[a] ?? b) != b || (ts[b] ?? a) != a) return false;
    st[a] = b;
    ts[b] = a;
  }
