bool isHappy(int n) {
  final seen = <int>{};
  while (n != 1 && seen.add(n)) {
    var next = 0;
    while (n > 0) {
      final d = n % 10;
      next += d * d;
      n ~/= 10;
    }
    n = next;
  }
  return n == 1;
}

void main() {
  print(isHappy(7));
  print(isHappy(4));
}
